    visited = set()
    components = []

    def bfs(start):
        q = deque([start])
        visited.add(start)
        comp = [start]
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
                    comp.append((nr, nc))
        return comp

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                comp = bfs((r,c))
                components.append(comp)
    return components

