# Now test with threshold 3
def transform_threshold(grid, thresh=3):
    from collections import Counter, deque
    rows, cols = len(grid), len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]

    out = [[bg]*cols for _ in range(rows)]
    visited = [[False]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                color = grid[r][c]
                comp = []
                q = deque([(r,c)])
                visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

                if len(comp) >= thresh:
                    r_min, r_max = min(x for x,y in comp), max(x for x,y in comp)
                    c_min, c_max = min(y for x,y in comp), max(y for x,y in comp)
                    for rr in range(r_min, r_max + 1):
                        for cc in range(c_min, c_max + 1):
                            out[rr][cc] = color
    return out

